#include <stdio.h>

struct Point { int x, y; };

void bump_val(struct Point p)  { p.x++; }     // changes only the copy
void bump_ptr(struct Point *p) { p->x++; }    // changes the caller's struct

int main(void) {
    struct Point a = {10, 20};
    struct Point b = a;          // member-wise copy
    bump_val(a);
    bump_ptr(&a);
    printf("a.x=%d b.x=%d\n", a.x, b.x);       // a.x=11 b.x=10
    printf("size=%zu\n", sizeof(struct Point)); // 8
    return 0;
}

