struct Person { char *name; int age; };
struct Person clone(const struct Person *p) {
    struct Person c = *p;                    // copies age and the pointer
    c.name = malloc(strlen(p->name) + 1);    // new buffer
    if (c.name) strcpy(c.name, p->name);     // deep copy of the string
    return c;
}

struct Point make(int x, int y) { return (struct Point){x, y}; }
double dist2(const struct Point *a, const struct Point *b) {
    double dx = a->x - b->x, dy = a->y - b->y;
    return dx * dx + dy * dy;
}

