typedef enum { V_INT, V_DBL, V_STR } Kind;
typedef struct {
    Kind kind;
    union { long i; double d; const char *s; };   // anonymous union (C11)
} Value;

void print(Value v) {
    switch (v.kind) {
    case V_INT: printf("%ld\n", v.i); break;
    case V_DBL: printf("%g\n", v.d); break;
    case V_STR: printf("%s\n", v.s); break;
    }
}

